CREATE FUNCTION app.progress_metrics(p_student uuid,p_from date,p_to date,p_exercise uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE result jsonb;today date=(now() AT TIME ZONE 'America/Asuncion')::date;
BEGIN
 IF NOT app.progress_access(p_student,'metrics') THEN RAISE EXCEPTION 'STUDENT_NOT_FOUND';END IF;
 IF p_from IS NULL OR p_to IS NULL OR p_from>p_to OR p_to-p_from>365 OR p_from<'2000-01-01' OR p_to>today THEN RAISE EXCEPTION 'INVALID_PROGRESS';END IF;
 WITH session_base AS MATERIALIZED(SELECT * FROM public.workout_sessions WHERE organization_id=app.tenant() AND student_id=p_student AND scheduled_on BETWEEN p_from AND p_to),
 set_counts AS(SELECT r.session_id,count(*) total,count(*)FILTER(WHERE r.state='recorded') recorded FROM public.workout_sets r JOIN session_base s ON s.id=r.session_id AND s.organization_id=r.organization_id GROUP BY r.session_id),
 sessions AS MATERIALIZED(SELECT s.*,coalesce(c.total,0) total,coalesce(c.recorded,0) recorded FROM session_base s LEFT JOIN set_counts c ON c.session_id=s.id),
 facts AS MATERIALIZED(SELECT s.id session_id,s.scheduled_on,(e.value->>'exerciseId')::uuid exercise_id,e.value->'snapshot'->>'name' name,r.metric,r.weight_kg,r.reps,r.seconds,r.distance_meters,r.rpe FROM sessions s CROSS JOIN LATERAL jsonb_array_elements(s.prescription->'exercises') e JOIN public.workout_sets r ON r.organization_id=s.organization_id AND r.session_id=s.id AND r.entry_id=(e.value->>'id')::uuid AND r.state='recorded' WHERE s.state='completed' AND s.recorded>0),
 raw_slots AS(SELECT a.state,a.cancelled_at,(a.starts_on+((w.ordinality-1)*7)::integer+(d.value->>'weekday')::integer-1) slot_day FROM public.program_assignments a JOIN public.program_versions v ON v.organization_id=a.organization_id AND v.id=a.version_id CROSS JOIN LATERAL jsonb_array_elements(v.snapshot->'weeks')WITH ORDINALITY w CROSS JOIN LATERAL jsonb_array_elements(w.value->'days')d WHERE a.organization_id=app.tenant() AND a.student_id=p_student AND a.starts_on<=p_to AND a.ends_on>=p_from),
 day_plan AS MATERIALIZED(SELECT slot_day,bool_or(state='active' OR slot_day<=(cancelled_at AT TIME ZONE 'America/Asuncion')::date OR EXISTS(SELECT 1 FROM sessions s WHERE s.scheduled_on=slot_day AND s.state='completed' AND s.recorded>0)) eligible FROM raw_slots WHERE slot_day BETWEEN p_from AND p_to GROUP BY slot_day),
 plan AS MATERIALIZED(SELECT *,EXISTS(SELECT 1 FROM sessions s WHERE s.scheduled_on=p.slot_day AND s.state='completed' AND s.recorded>0) completed FROM day_plan p),
 weekly_facts AS(SELECT date_trunc('week',scheduled_on)::date week,count(*) recorded_sets,coalesce(sum(weight_kg*reps)FILTER(WHERE metric='reps' AND weight_kg IS NOT NULL),0) volume,count(*)FILTER(WHERE metric='reps' AND weight_kg IS NULL) unweighted FROM facts GROUP BY 1),
 weekly_plan AS(SELECT date_trunc('week',slot_day)::date week,count(*)FILTER(WHERE eligible) expected,count(*)FILTER(WHERE eligible AND completed) completed FROM plan GROUP BY 1),
 exercise_stats AS(SELECT exercise_id,metric,(array_agg(name ORDER BY scheduled_on DESC,session_id DESC))[1] name,count(*) sets,coalesce(sum(weight_kg*reps)FILTER(WHERE metric='reps' AND weight_kg IS NOT NULL),0) volume,count(*)FILTER(WHERE metric='reps' AND weight_kg IS NULL) unweighted,max(weight_kg)FILTER(WHERE metric='reps') best_load,(array_agg(reps ORDER BY weight_kg DESC NULLS LAST,reps DESC)FILTER(WHERE metric='reps' AND weight_kg IS NOT NULL))[1] best_load_reps,max(seconds) best_seconds,max(distance_meters) best_distance FROM facts GROUP BY exercise_id,metric),
 trend AS(SELECT exercise_id,metric,scheduled_on,coalesce(sum(weight_kg*reps)FILTER(WHERE metric='reps' AND weight_kg IS NOT NULL),0) volume,max(weight_kg)FILTER(WHERE metric='reps') best_load,max(seconds) best_seconds,max(distance_meters) best_distance,count(*) sets FROM facts WHERE p_exercise IS NULL OR exercise_id=p_exercise GROUP BY exercise_id,metric,scheduled_on),
 recent AS(SELECT coalesce(sum(weight_kg*reps)FILTER(WHERE metric='reps' AND weight_kg IS NOT NULL AND scheduled_on>p_to-7),0) volume,coalesce(sum(weight_kg*reps)FILTER(WHERE metric='reps' AND weight_kg IS NOT NULL AND scheduled_on BETWEEN p_to-13 AND p_to-7),0) previous_volume FROM facts),
 last_session AS(SELECT max(completed_at) last_completed FROM public.workout_sessions WHERE organization_id=app.tenant() AND student_id=p_student AND state='completed' AND EXISTS(SELECT 1 FROM public.workout_sets r WHERE r.organization_id=app.tenant() AND r.session_id=workout_sessions.id AND r.state='recorded'))
 SELECT jsonb_build_object(
  'studentId',p_student,'from',p_from,'to',p_to,'timezone','America/Asuncion','dateBasis','scheduled_on',
  'summary',jsonb_build_object('sessions',(SELECT count(*) FROM sessions WHERE state='completed' AND recorded>0),'partialSessions',(SELECT count(*) FROM sessions WHERE state='completed' AND recorded>0 AND recorded<total),'inProgress',(SELECT count(*) FROM sessions WHERE state='in_progress'),'recordedSets',(SELECT count(*) FROM facts),'volumeKgReps',(SELECT coalesce(sum(weight_kg*reps)FILTER(WHERE metric='reps' AND weight_kg IS NOT NULL),0) FROM facts),'unweightedSets',(SELECT count(*) FROM facts WHERE metric='reps' AND weight_kg IS NULL),'expectedDays',(SELECT count(*) FROM plan WHERE eligible),'completedDays',(SELECT count(*) FROM plan WHERE eligible AND completed),'missedDays',(SELECT count(*) FROM plan WHERE eligible AND NOT completed AND slot_day<today),'todayPending',(SELECT count(*) FROM plan WHERE eligible AND NOT completed AND slot_day=today),'cancelledDays',(SELECT count(*) FROM plan WHERE NOT eligible),'lastCompletedAt',(SELECT last_completed FROM last_session)),
  'comparison',jsonb_build_object('last7Volume',(SELECT volume FROM recent),'previous7Volume',(SELECT previous_volume FROM recent)),
  'weekly',(SELECT coalesce(jsonb_agg(jsonb_build_object('week',w.week::date,'volumeKgReps',coalesce(f.volume,0),'recordedSets',coalesce(f.recorded_sets,0),'unweightedSets',coalesce(f.unweighted,0),'expectedDays',coalesce(p.expected,0),'completedDays',coalesce(p.completed,0))ORDER BY w.week),'[]')FROM generate_series(date_trunc('week',p_from::timestamp),date_trunc('week',p_to::timestamp),interval '7 days')w(week) LEFT JOIN weekly_facts f ON f.week=w.week::date LEFT JOIN weekly_plan p ON p.week=w.week::date),
  'exercises',(SELECT coalesce(jsonb_agg(jsonb_build_object('exerciseId',exercise_id,'metric',metric,'name',name,'recordedSets',sets,'volumeKgReps',volume,'unweightedSets',unweighted,'bestLoadKg',best_load,'bestLoadReps',best_load_reps,'bestSeconds',best_seconds,'bestDistanceMeters',best_distance)ORDER BY name,exercise_id,metric),'[]')FROM exercise_stats),
  'trend',(SELECT coalesce(jsonb_agg(jsonb_build_object('exerciseId',exercise_id,'metric',metric,'date',scheduled_on,'volumeKgReps',volume,'bestLoadKg',best_load,'bestSeconds',best_seconds,'bestDistanceMeters',best_distance,'recordedSets',sets)ORDER BY scheduled_on,exercise_id,metric),'[]')FROM trend),
  'access',jsonb_build_object('measurements',app.progress_access(p_student,'measurements'),'photos',app.progress_access(p_student,'photos')),
  'activity',jsonb_build_object('lastCompletedAt',l.last_completed,'daysInactive',greatest(0,today-coalesce((l.last_completed AT TIME ZONE 'America/Asuncion')::date,st.created_at::date)),'enabled',coalesce(a.enabled,true),'thresholdDays',coalesce(a.days,14),'revision',coalesce(a.revision,0),'flagged',st.status='active' AND coalesce(a.enabled,true) AND today-coalesce((l.last_completed AT TIME ZONE 'America/Asuncion')::date,st.created_at::date)>=coalesce(a.days,14))
 ) INTO result FROM public.students st CROSS JOIN last_session l LEFT JOIN public.progress_alert_settings a ON a.organization_id=st.organization_id AND a.student_id=st.id AND a.professional_user_id=app.actor() WHERE st.organization_id=app.tenant() AND st.id=p_student;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION app.progress_metrics(uuid,date,date,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.progress_metrics(uuid,date,date,uuid) TO forma_api;
